static uint16 TIFFClampDoubleToUInt16( double val ) /* <=== TIFFClampDoubleToUInt16 */ 
{
    if( val < 0 )
        return 0;
    if( val > 65535 || val != val )
        return 65535;
    return (uint16)val;
}

static int32 TIFFClampDoubleToInt32( double val ) /* <=== TIFFClampDoubleToInt32 */ 
{
    if( val > 0x7FFFFFFF )
        return 0x7FFFFFFF;
    if( val < -0x7FFFFFFF-1 || val != val )
        return -0x7FFFFFFF-1;
    return (int32)val;
}

